import importlib.util,json,pathlib
p=pathlib.Path(__file__).resolve().parent/'isolated_db.py'; spec=importlib.util.spec_from_file_location('c5db',p); m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m)
pg="SELECT json_build_object('version',version(),'server_version',current_setting('server_version'),'fsync',current_setting('fsync'),'full_page_writes',current_setting('full_page_writes'),'synchronous_commit',current_setting('synchronous_commit'),'default_transaction_isolation',current_setting('default_transaction_isolation'),'server_encoding',current_setting('server_encoding'),'collation',(SELECT datcollate FROM pg_database WHERE datname=current_database()),'data_directory',current_setting('data_directory'));"
my="SELECT JSON_OBJECT('version',VERSION(),'version_comment',@@version_comment,'default_storage_engine',@@default_storage_engine,'transaction_isolation',@@transaction_isolation,'innodb_flush_log_at_trx_commit',@@innodb_flush_log_at_trx_commit,'sync_binlog',@@sync_binlog,'innodb_rollback_on_timeout',@@innodb_rollback_on_timeout,'collation_server',@@collation_server,'collation_database',@@collation_database,'lower_case_table_names',@@lower_case_table_names,'datadir',@@datadir,'innodb_buffer_pool_size',@@innodb_buffer_pool_size,'innodb_redo_log_capacity',@@innodb_redo_log_capacity);"
result={'initial_orbstack_status':'Stopped','orbstack_started_for':'C5 authorized disposable synthetic work','image_downloads':False,'physical_medium':'Docker tmpfs in OrbStack Linux VM; RAM-backed. fsync settings recorded but no power-loss durability claim.'}
for engine,query in [('pg',pg),('mysql',my)]:
 s,i=m.owned(engine); result[engine]={'configuration':json.loads(m.sql(engine,query)),'id':s['id'],'image_reference':s['image'],'image_id':i['Image'],'endpoint':s['endpoint'],'memory_limit_bytes':i['HostConfig']['Memory'],'memory_swap_limit_bytes':i['HostConfig']['MemorySwap'],'nano_cpus':i['HostConfig']['NanoCpus'],'pids_limit':i['HostConfig']['PidsLimit'],'readonly_rootfs':i['HostConfig']['ReadonlyRootfs'],'tmpfs':i['HostConfig']['Tmpfs'],'mounts':i['Mounts'],'ports':i['NetworkSettings']['Ports'],'data_filesystem':m.run(['exec',s['id'],'df','-T','/var/lib/postgresql/data' if engine=='pg' else '/var/lib/mysql'])}
probe="SELECT JSON_OBJECT('collation','utf8mb4_0900_bin','trailing_space_equal',_utf8mb4'a' COLLATE utf8mb4_0900_bin = _utf8mb4'a ','case_equal',_utf8mb4'a' COLLATE utf8mb4_0900_bin = _utf8mb4'A','accent_equal',_utf8mb4'e' COLLATE utf8mb4_0900_bin = _utf8mb4'é','pad_attribute',(SELECT PAD_ATTRIBUTE FROM INFORMATION_SCHEMA.COLLATIONS WHERE COLLATION_NAME='utf8mb4_0900_bin'));"
result['mysql']['binary_collation_probe']=json.loads(m.sql('mysql',probe))
m.save(p.parent/'environment-receipt.json',result); print(json.dumps(result,indent=2))
